package queue

import "testing"

func TestPushPop(t *testing.T) {
	q := NewQueue[int]()
	q.Push(1)
	q.Push(2)
	q.Push(3)
	v, ok := q.Pop()
	if !ok || v != 1 {
		t.Fatalf("expected 1 ok=true, got %d ok=%v", v, ok)
	}
	v, ok = q.Pop()
	if !ok || v != 2 {
		t.Fatalf("expected 2 ok=true, got %d ok=%v", v, ok)
	}
}

func TestPopEmpty(t *testing.T) {
	q := NewQueue[string]()
	_, ok := q.Pop()
	if ok {
		t.Fatal("expected ok=false for empty queue")
	}
}

func TestPeek(t *testing.T) {
	q := NewQueue[int]()
	q.Push(42)
	v, ok := q.Peek()
	if !ok || v != 42 {
		t.Fatalf("expected 42 ok=true, got %d ok=%v", v, ok)
	}
	if q.Len() != 1 {
		t.Fatalf("Peek must not remove element")
	}
}

func TestLenAndIsEmpty(t *testing.T) {
	q := NewQueue[float64]()
	if !q.IsEmpty() {
		t.Fatal("expected empty")
	}
	q.Push(1.0)
	q.Push(2.0)
	if q.Len() != 2 {
		t.Fatalf("expected 2, got %d", q.Len())
	}
	if q.IsEmpty() {
		t.Fatal("expected not empty")
	}
}

func TestFIFOOrder(t *testing.T) {
	q := NewQueue[int]()
	for i := 0; i < 5; i++ {
		q.Push(i)
	}
	for i := 0; i < 5; i++ {
		v, ok := q.Pop()
		if !ok || v != i {
			t.Fatalf("expected %d got %d ok=%v", i, v, ok)
		}
	}
}
